import { GameEngine } from './src/engine.js';
import { GameRenderer } from './src/renderer.js';
import { audioManager } from './src/audio.js';
import { CHARACTERS, STAGES, ARTIFACTS, TALENTS, DAILY_CHALLENGES, getStage } from './src/content.js';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const SAVE_KEY='xiyou-commercial-save-v1';
const defaultSave={unlockedStage:1,talents:{},talentPoints:0,bestScore:0,wins:0,streak:0,scrolls:0,lastRun:null,muted:false,volume:.72};
let save=loadSave();
let selectedCharacter='wukong', selectedStage=1, engine=null, renderer=null, raf=0,lastFrame=0,lastInput={x:0,y:0},toastTimer=0;
const charIcons={wukong:'猿',tangseng:'僧',bajie:'耙',shajing:'沙'};
const stageIcons={forest:'林',sand:'漠',snow:'雪',fire:'焰',water:'水',temple:'殿'};

function loadSave(){try{return {...defaultSave,...JSON.parse(localStorage.getItem(SAVE_KEY)||'{}')}}catch{return {...defaultSave}}}
function persist(){localStorage.setItem(SAVE_KEY,JSON.stringify(save)); updateHomeMeta()}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
function showScreen(id){$$('.screen').forEach(s=>s.classList.toggle('active',s.id===id+'Screen')); if(id==='home') updateHomeMeta(); if(id==='chapters') renderChapters(); if(id==='talents') renderTalents(); if(id==='daily') renderDaily(); if(id==='select') renderSelect()}
function updateHomeMeta(){$('#continueMeta').textContent=save.lastRun?`${save.lastRun.characterName} · ${save.lastRun.stageName}`:'未有记录';$('#talentMeta').textContent=`${save.talentPoints} 点悟性`;$('#bestScore').textContent=save.bestScore.toLocaleString();$('#winStreak').textContent=save.streak;$('#scrolls').textContent=save.scrolls}
function dateSeed(){const d=new Date();return d.getFullYear()*10000+(d.getMonth()+1)*100+d.getDate()}
function renderChapters(){const grid=$('#chapterGrid');grid.innerHTML='';for(let i=0;i<9;i++){const first=STAGES[i*9], last=STAGES[i*9+8], unlocked=save.unlockedStage>=i*9+1;const el=document.createElement('article');el.className=`chapter-card ${unlocked?'':'locked'} ${selectedStage>=i*9+1&&selectedStage<=i*9+9?'current':''}`;el.innerHTML=`<span class="num">CHAPTER ${String(i+1).padStart(2,'0')}</span><h3>${first.chapterName||`第${['一','二','三','四','五','六','七','八','九'][i]}章`}</h3><p>${first.location} → ${last.location}</p><span class="boss">${unlocked?'终妖王 · '+last.boss:'锁定 · 通关前章解锁'}</span>`;if(unlocked)el.addEventListener('click',()=>{selectedStage=i*9+1;showScreen('select')});grid.appendChild(el)}}
function renderTalents(){const grid=$('#talentGrid');$('#talentPoints').textContent=save.talentPoints;grid.innerHTML='';TALENTS.forEach(t=>{const level=save.talents[t.id]||0,maxed=level>=t.maxLevel,cost=t.baseCost*(level+1);const el=document.createElement('article');el.className=`talent-card ${maxed?'maxed':''}`;el.innerHTML=`<h3>${t.name} <span style="color:var(--gold);font:10px Space Mono">${level}/${t.maxLevel}</span></h3><p>${t.description}</p><div class="talent-foot">${maxed?'已圆满':`${cost} 悟性 · 修炼`}</div>`;if(!maxed)el.addEventListener('click',()=>{if(save.talentPoints<cost){toast('悟性不足：完成关卡或今日禅试获取');return}save.talentPoints-=cost;save.talents[t.id]=level+1;persist();renderTalents();audioManager.play('level');toast(`${t.name} · 修行 +1`)});grid.appendChild(el)})}
function renderDaily(){const challenge=DAILY_CHALLENGES[dateSeed()%DAILY_CHALLENGES.length];$('#dailyCard').innerHTML=`<span class="daily-tag">${challenge.tag}</span><h3>${challenge.name}</h3><p>${challenge.description}</p><p style="color:var(--gold)">奖励：${challenge.reward} · 今日种子 ${dateSeed()}</p><button id="dailyStart" class="btn btn-primary">接受禅试</button>`;$('#dailyStart').addEventListener('click',()=>{selectedStage=challenge.stageId;selectedCharacter=challenge.characterId||'wukong';showScreen('game');launchGame(challenge.seed||dateSeed(),challenge.modifiers||{})})}
function renderSelect(){const grid=$('#characterGrid');grid.innerHTML='';CHARACTERS.forEach(c=>{const el=document.createElement('article');el.className=`character-card ${c.id===selectedCharacter?'selected':''}`;el.innerHTML=`<div class="portrait" style="color:${c.color}">${charIcons[c.id]}</div><h3>${c.name}</h3><p>${c.title}<br>${c.description}</p><span class="character-weapon">本命 · ${c.weapon}</span>`;el.addEventListener('click',()=>{selectedCharacter=c.id;renderSelect();audioManager.play('click')});grid.appendChild(el)});const select=$('#stageSelect');select.innerHTML='';STAGES.forEach((s,i)=>{const opt=document.createElement('option');opt.value=s.id;opt.textContent=`第${s.id}难 · ${s.location} · ${s.name}`;opt.disabled=s.id>save.unlockedStage;opt.selected=s.id===selectedStage;select.appendChild(opt)});select.onchange=()=>{selectedStage=Number(select.value);updateStageLabel()};updateStageLabel()}
function updateStageLabel(){const s=getStage(selectedStage);$('#selectedStageName').textContent=s.name;$('#selectedStageBoss').textContent=`首领：${s.boss} · ${s.description}`}
function startSelected(){showScreen('game');launchGame(Math.floor(Math.random()*2147483647),{})}
function launchGame(seed,modifiers){if(engine){engine.dispose();} const talentStats={};for(const t of TALENTS){const lv=save.talents[t.id]||0;if(lv)talentStats[t.stat]=(talentStats[t.stat]||0)+t.value*lv} engine=new GameEngine({characterId:selectedCharacter,stageId:selectedStage,seed,talents:talentStats,difficulty:modifiers.difficulty||'normal',debug:false,onEvent:onEvent});renderer=new GameRenderer($('#gameCanvas'),{width:900,height:1600,pixelRatio:Math.min(2,window.devicePixelRatio||1),quality:window.innerWidth<600?'high':'high'});audioManager.unlock();audioManager.startMusic(getStage(selectedStage).theme);audioManager.setMuted(save.muted);audioManager.setVolume(save.volume);$('#pauseOverlay').classList.add('hidden');$('#upgradeOverlay').classList.add('hidden');$('#resultOverlay').classList.add('hidden');$('#gameChapter').textContent=`第${selectedStage}难 · ${getStage(selectedStage).location}`;lastFrame=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(gameLoop);toast(`${CHARACTERS.find(c=>c.id===selectedCharacter).name}，第${selectedStage}难启程`)}
function onEvent(event){if(event.type==='upgrade'){renderUpgrade(event.choices);audioManager.play('level')}if(event.type==='hit')audioManager.play('hit');if(event.type==='kill')audioManager.play('kill');if(event.type==='elite')audioManager.play('elite');if(event.type==='boss')audioManager.play('boss');if(event.type==='pickup')audioManager.play('pickup');if(event.type==='dash')audioManager.play('dash');if(event.type==='win'||event.type==='lose'){audioManager.play(event.type);setTimeout(()=>finishGame(event.type),80)}}
function gameLoop(now){if(!engine||!renderer)return;const dt=Math.min(.05,(now-lastFrame)/1000||0);lastFrame=now;engine.update(dt,lastInput);const state=engine.getSnapshot();renderer.render(state,dt);updateHUD(state);raf=requestAnimationFrame(gameLoop)}
function updateHUD(state){const mins=Math.floor(state.time/60),secs=Math.floor(state.time%60);$('#gameTimer').textContent=`${mins}:${String(secs).padStart(2,'0')}`;$('#timeProgress').style.width=`${Math.min(100,state.time/600*100)}%`;$('#gameKills').textContent=`${state.kills} 击破`;$('#levelLabel').textContent=`Lv.${state.player.level}`;$('#xpProgress').style.width=`${Math.min(100,state.player.xp/state.player.xpNext*100)}%`;const slots=$('#buildSlots');slots.innerHTML=state.skills.map(s=>`<span class="skill-slot" title="${s.name}">${s.icon||'✦'}<em>${s.level}</em></span>`).join('')}
function renderUpgrade(choices){const box=$('#upgradeChoices');box.innerHTML=choices.map(c=>`<button class="upgrade-choice" data-id="${c.id}"><div class="card-icon">${c.icon||'✦'}</div><h3>${c.name}</h3><p>${c.description}</p><small>${c.level?`当前 Lv.${c.level}`:'新法宝'}</small></button>`).join('');$$('.upgrade-choice',box).forEach(btn=>btn.addEventListener('click',()=>{engine.chooseUpgrade(btn.dataset.id);$('#upgradeOverlay').classList.add('hidden');audioManager.play('click')}));$('#upgradeOverlay').classList.remove('hidden')}
function finishGame(outcome){if(!engine)return;const state=engine.getSnapshot();$('#resultOverlay').classList.remove('hidden');const won=outcome==='win';$('#resultEyebrow').textContent=won?'THE CALAMITY IS BROKEN':'THE JOURNEY ENDS HERE';$('#resultTitle').textContent=won?'此难已破':'暂渡未成';$('#resultText').textContent=won?`你在${getStage(selectedStage).location}守住了取经路。功德 +${Math.max(1,Math.floor(state.kills/8))}。`:`妖风太盛，先回高老庄整备，再来一战。`;$('#resultKills').textContent=state.kills;$('#resultLevel').textContent=state.player.level;$('#resultTime').textContent=`${Math.floor(state.time/60)}:${String(Math.floor(state.time%60)).padStart(2,'0')}`;const score=state.kills*10+state.player.level*100+(won?1000:0);save.bestScore=Math.max(save.bestScore,score);save.lastRun={characterName:state.character.name,stageName:getStage(selectedStage).name};if(won){save.wins++;save.streak++;save.scrolls+=1;save.talentPoints+=2;if(selectedStage===save.unlockedStage&&save.unlockedStage<81)save.unlockedStage++;}else save.streak=0;persist();audioManager.stopMusic()}
function quitGame(){if(engine){engine.dispose();engine=null}audioManager.stopMusic();cancelAnimationFrame(raf);showScreen('home')}
function togglePause(){if(!engine)return;const s=engine.getSnapshot();if(s.status==='paused'){engine.resume();$('#pauseOverlay').classList.add('hidden')}else if(s.status==='playing'){engine.pause();$('#pauseOverlay').classList.remove('hidden')}}
function setupInput(){window.addEventListener('keydown',e=>{if(e.key==='Escape'||e.key.toLowerCase()==='p')togglePause();if(e.key===' '){e.preventDefault();engine?.useDash(lastInput)}const k=e.key.toLowerCase();lastInput={x:(k==='d'||k==='arrowright'?1:k==='a'||k==='arrowleft'?-1:0),y:(k==='s'||k==='arrowdown'?1:k==='w'||k==='arrowup'?-1:0)}});window.addEventListener('keyup',e=>{if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))lastInput={x:0,y:0}});const joy=$('#joystick');let active=false;let center={x:0,y:0};const move=e=>{if(!active)return;const r=joy.getBoundingClientRect(),p=e.touches?e.touches[0]:e;const dx=p.clientX-(r.left+r.width/2),dy=p.clientY-(r.top+r.height/2),m=Math.hypot(dx,dy)||1;lastInput={x:Math.max(-1,Math.min(1,dx/35)),y:Math.max(-1,Math.min(1,dy/35))};joy.querySelector('span').style.transform=`translate(${Math.max(-24,Math.min(24,dx))}px,${Math.max(-24,Math.min(24,dy))}px)`};joy.addEventListener('pointerdown',e=>{active=true;joy.setPointerCapture(e.pointerId);move(e)});joy.addEventListener('pointermove',move);joy.addEventListener('pointerup',()=>{active=false;lastInput={x:0,y:0};joy.querySelector('span').style.transform=''});$('#dashBtn').addEventListener('click',()=>engine?.useDash(lastInput.x||1,lastInput.y||0))}

$$('[data-nav]').forEach(b=>b.addEventListener('click',()=>showScreen(b.dataset.nav)));$('#startBtn').addEventListener('click',()=>showScreen('select'));$('#continueBtn').addEventListener('click',()=>{if(save.lastRun){selectedStage=Math.min(save.unlockedStage,save.lastRun.stageId||save.unlockedStage);showScreen('select')}else showScreen('select')});$('#launchBtn').addEventListener('click',startSelected);$('#pauseBtn').addEventListener('click',togglePause);$('#resumeBtn').addEventListener('click',togglePause);$('#quitBtn').addEventListener('click',quitGame);$('#againBtn').addEventListener('click',()=>{showScreen('select');$('#resultOverlay').classList.add('hidden')});$('#homeBtn').addEventListener('click',()=>{showScreen('home');$('#resultOverlay').classList.add('hidden')});$('#helpBtn').addEventListener('click',()=>$('#helpDialog').showModal());$('#closeHelp').addEventListener('click',()=>$('#helpDialog').close());$('#soundBtn').addEventListener('click',()=>{save.muted=!save.muted;audioManager.setMuted(save.muted);persist();$('#soundBtn').textContent=save.muted?'○':'◖';toast(save.muted?'音效已静音':'音效已开启')});
updateHomeMeta();renderChapters();renderTalents();renderDaily();renderSelect();setupInput();
